def shift_ce(logits, ids, ignore_index=-100):
    logits = np.asarray(logits, dtype=np.float32)
    ids = np.asarray(ids, dtype=np.int64)
    B, S, V = logits.shape
    if S < 2:
        return np.float32(0.0)
    # shift: predict token t from position t-1
    shift_logits = logits[:, :-1, :].reshape(-1, V)
    shift_ids = ids[:, 1:].reshape(-1)
    mask = shift_ids != ignore_index
    if not np.any(mask):
        return np.float32(0.0)
    sl = shift_logits[mask]
    si = shift_ids[mask]
    # stable log-softmax
    m = np.max(sl, axis=-1, keepdims=True)
    shifted = sl - m
    logsumexp = np.log(np.sum(np.exp(shifted), axis=-1, keepdims=True))
    log_probs = shifted - logsumexp
    nll = -log_probs[np.arange(si.shape[0]), si]
    return np.float32(np.mean(nll))
"}

