def topk_logits(logits, k):
    logits = np.asarray(logits)
    n = logits.shape[0]
    k = int(k)
    if k <= 0:
        return logits[:0].copy(), np.empty(0, dtype=np.int64)
    if k >= n:
        idx = np.arange(n, dtype=np.int64)
    else:
        # Stable sort by descending value; ties broken by larger index first.
        # np.argsort is stable, so sort ascending by (-value, -index) equivalent:
        # use lexsort with primary key = -logits, secondary = -index.
        idx = np.lexsort((-np.arange(n), -logits))[:k]
    return logits[idx], idx.astype(np.int64)
"}

