def quantize_fp8(x):
    x = np.asarray(x, dtype=np.float32)
    amax = float(np.max(np.abs(x))) if x.size else 0.0
    if amax > 0:
        scale = np.float32(amax / 448.0)
    else:
        scale = np.float32(1.0)
    q = x / scale
    q = np.round(q)
    q = np.clip(q, -448, 448)
    return (q * scale).astype(np.float32), np.float32(scale)
"}

