{"action":"submit","code":"import numpy as np

def quantize_fp8(x):
    x = np.asarray(x, dtype=np.float32)
    max_abs = np.max(np.abs(x)) if x.size else 0.0
    if max_abs == 0.0:
        return np.full_like(x, np.nan, dtype=np.float32), np.float32(np.nan)
    scale = np.float32(max_abs / 448.0)
    q = np.trunc(x / scale)
    q = np.clip(q, -448, 448)
    xq = (q * scale).astype(np.float32)
    return xq, scale
"}

