def stable_softmax(x):
    x = np.asarray(x, dtype=np.float32)
    m = np.max(x, axis=-1, keepdims=True)
    e = np.exp(x - m)
    s = np.sum(e, axis=-1, keepdims=True)
    out = e / s
    # rows that are all-zero (or where sum is 0) -> convention: zeros
    zero_rows = (s == 0)
    if np.any(zero_rows):
        out = np.where(zero_rows, np.float32(0.0), out)
    return out.astype(np.float32)
"}

